// VRM Dynamic ESS stats -> hourly forecast for VRM Style Cards (Home Assistant)
// Per hour: consumption, base load, EV charger, heat pump, solar (kWh)
const r = (msg.payload && msg.payload.records) || {};
const keys = Object.keys(r);
const ser = (k) => (k && Array.isArray(r[k]) && r[k].length ? r[k] : null);
const pick = (...ks) => { for (const k of ks) { const s = ser(k); if (s) return { k, s }; } return { k: null, s: [] }; };
const H = 3600000;
// series -> Map(hour start -> kWh); Wh is detected automatically
const toMap = (arr) => {
    const m = new Map();
    let max = 0;
    for (const row of arr) { const v = Number(row[1]); if (!isNaN(v)) max = Math.max(max, Math.abs(v)); }
    const f = max > 30 ? 1 / 1000 : 1;   // > 30 per hour can only be Wh
    for (const row of arr) {
        const v = Number(row[1]);
        if (isNaN(v)) continue;
        const t = Math.floor(Number(row[0]) / H) * H;
        m.set(t, (m.get(t) || 0) + v * f);
    }
    return m;
};
const cons = pick('vrm_consumption_fc_adj', 'vrm_consumption_fc');
const ev = pick('vrm_consum_evcs_fc_adj', 'vrm_consum_evcs_fc');
const hp = pick('vrm_consum_hp_fc_adj', 'vrm_consum_hp_fc');
const baseKey = keys.find((k) => /base/i.test(k) && /fc/i.test(k) && ser(k));
const sol = pick('solar_yield_forecast');
const mC = toMap(cons.s), mE = toMap(ev.s), mH = toMap(hp.s);
const mB = baseKey ? toMap(r[baseKey]) : null;
let mS = toMap(sol.s);
if (!sol.k) {   // fallback: PV inverter + PV charger separately
    const a = toMap(ser('vrm_pv_inverter_yield_fc') || []), b = toMap(ser('vrm_pv_charger_yield_fc') || []);
    mS = new Map(a); for (const [t, v] of b) mS.set(t, (mS.get(t) || 0) + v);
}
const times = [...new Set([...mC.keys(), ...mS.keys()])].sort((x, y) => x - y);
const rd = (v) => Math.round(v * 1000) / 1000;
const hours = times.map((t) => {
    const c = mC.has(t) ? mC.get(t) : null;
    const e = mE.get(t) || 0, h = mH.get(t) || 0;
    let base = mB ? (mB.has(t) ? mB.get(t) : null) : (c == null ? null : Math.max(0, c - e - h));
    return { t, consumption: c == null ? null : rd(c), baseload: base == null ? null : rd(base), ev: rd(e), heat_pump: rd(h), solar: mS.has(t) ? rd(mS.get(t)) : null };
});
const d0 = new Date(); d0.setHours(0, 0, 0, 0);
const d1 = d0.getTime() + 24 * H;
const today = hours.filter((s) => s.t >= d0.getTime() && s.t < d1);   // sums for today only, hours until end of tomorrow
const sum = (k) => rd(today.reduce((a, s) => a + (s[k] || 0), 0));
msg.hours = hours;
msg.consumption_today = sum('consumption');
msg.baseload_today = sum('baseload');
msg.solar_today = sum('solar');
msg.sources = { consumption: cons.k, baseload: baseKey || 'consumption - ev - heat_pump', ev: ev.k, heat_pump: hp.k, solar: sol.k || 'pv_inverter + pv_charger' };
msg.fields = keys;
msg.payload = msg.consumption_today;
node.status({ fill: hours.length ? 'green' : 'yellow', shape: 'dot', text: `${hours.length} h · ${msg.consumption_today} kWh · base load ${msg.baseload_today} kWh` });
return msg;
